const YEARS = { en: ["years", "y"], fr: ["ans", "a"], nl: ["jaar", "j"], de: ["Jahre", "J."], pl: ["lat", "l."] };

const li = () => LANGS.indexOf(current);

export function initLang() {
  const fromUrl = new URLSearchParams(location.search).get("lang") || new URLSearchParams(location.hash.split("?")[1] || "").get("lang");
  let stored = null;
  try { stored = localStorage.getItem("cb-lang"); } catch {}
  const nav = (navigator.languages || [navigator.language || "en"]).map((l) => l.slice(0, 2).toLowerCase());
  current = [fromUrl, stored, ...nav].find((l) => LANGS.includes(l)) || "en";
  document.documentElement.lang = current;
}

export function setLang(l) {
  if (!LANGS.includes(l)) return;
  current = l;
  document.documentElement.lang = l;
  try { localStorage.setItem("cb-lang", l); } catch {}
}

export const lang = () => current;

export function t(key, vars = {}) {
  const s = STR[current][key] ?? STR.en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? vars[k] : `{${k}}`));
}

export const rubricName = (code) => RUBRICS[code]?.[li()] ?? code;
export const groupName = (g) => GROUPS[g]?.[li()] ?? g;
export const segName = (s) => (SEGMENTS[s] ? `${s} · ${SEGMENTS[s][li()]}` : s);
export const bodyName = (b) => BODIES[b]?.[li()] ?? b;
export const ptName = (p) => PT[p]?.[li()] ?? p;
export function ageLabel(a, short = false) {
  const [w, s] = YEARS[current];
  const r = a.replace("-", "–");
  return short ? `${r} ${s}` : `${r} ${w}`;
}

export function applyStatic() {
  document.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll("[data-i18n-title]").forEach((el) => {
    el.title = t(el.dataset.i18nTitle);
    el.setAttribute("aria-label", t(el.dataset.i18nTitle));
  });
}
